                        + "				  lv.userName AS uname, sg.name as acName,u.description as userDescription\n"
                        + "                  FROM  " + DmServer.dbCompany + ".dbo.linkVerification AS lv          \n"
                        + "                  left join  " + DmServer.dbCompany + ".dbo.usermast as u ON u.user_name = lv.userName\n"
                        + "				  left join  " + DmServer.dbCompany + ".dbo.userLinkAccount as ul ON u.user_name = ul.user_Name\n"
                        + "				  left join subGroup as sg on ul.subCode = sg.subCode\n "
                        + "              ) ";
