                            //Inserting group under
                            sqlQuery = "Insert Into AcGroupPath(GroupCode,SNo,GroupUnder) "
                                    + "select '" + codeValue + "' as GroupCode,isNull(max(sno),0) + 1,'" + codeValue1 + "' as GroupUnder "
                                    + "from AcGroupPath where groupCode = '" + codeValue + "'";
