    private void iniReceiptMapping(Connection cnTemp) throws Exception {
        DmPreparedStatement psTemp = null;
        ResultSet rsTemp = null;
        String sqlQuery = "", codeValue = "";
        ProjectVoucherCategory pvc = new ProjectVoucherCategory();
        try {

            if (DmShared.vNull(DmServer.executeScalar("Select Count(*) As Cnt From receiptBookMapping;", cnTemp)) <= 0) {

                sqlQuery = "insert into receiptBookMapping (entryPoint, v_Type, v_Receipt,v_Refund, isDefault)      "
                        + "select entryPoint, max(v_Type) as v_Type, max(v_Receipt) as v_Receipt,max(v_Refund) as v_Refund, max(isDefault) as isDefault     "
                        + "from (     "
                        + "select '" + new pmOPD().CONSULTATION.caption + "' as entryPoint, vt.v_Type, v_Receipt,v_Refund, (case when vt.short_name = 'OPD' then 1 else 0 end) as isDefault     "
                        + "from voucher_Type vt      "
                        + "left join (     "
                        + "select  v_Type as v_Receipt     "
                        + "from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.OPD_REGISTRATION_RECEIPT + "')     "
                        + ") vtr on 1=1       "
                        + "left join (     "
                        + "select  v_Type as v_Refund     "
                        + "from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.OPD_REFUND_RECEIPT + "')     "
                        + ") vtrf on 1=1 "
                        + "where vt.short_Name in ('" + pvc.OPD + "', '" + pvc.EMERGENCY_OPD + "', '" + pvc.PAY_CLINIC + "')     "
                        + "union all      "
                        + "select '" + new pmOPD().OPD_SERVICES.caption + "' as entryPoint, v_Type, v_Receipt,v_Refund, 1 as isDefault     "
                        + "from voucher_Type vt      "
                        + "left join (     "
                        + "select  v_Type as v_Receipt     "
                        + "from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.OPD_SERVICE_RECEIPT + "')     "
                        + ") vtr on 1=1       "
                        + "left join (     "
                        + "select  v_Type as v_Refund     "
                        + "								from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.OPD_REFUND_RECEIPT + "')     "
                        + ") vtrf on 1=1 "
                        + "where vt.short_Name in ('" + pvc.OPD_SERVICE + "')     "
                        + "union all      "
                        + "select '" + new pmOPD().UHID.caption + "' as entryPoint, v_Type, v_Receipt,v_Refund, 1 as isDefault     "
                        + "from voucher_Type vt      "
                        + "left join (     "
                        + "select  v_Type as v_Receipt     "
                        + "from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.UHID_REGISTRATION_RECEIPT + "')     "
                        + ") vtr on 1=1      "
                        + "left join (     "
                        + "select  v_Type as v_Refund     "
                        + "from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.OPD_REFUND_RECEIPT + "')     "
                        + ") vtrf on 1=1 "
                        + "where vt.short_Name in ('" + pvc.UHID + "')     "
                        + "union all      "
                        + "select '" + new pmDiagnostic().LAB_REGISTRATION.caption + "' as entryPoint, v_Type, v_Receipt,v_Refund, 1 as isDefault     "
                        + "from voucher_Type vt      "
                        + "left join (     "
                        + "select  v_Type as v_Receipt     "
                        + "from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.LAB_REGISTRATION_RECEIPT + "')     "
                        + ") vtr on 1=1        "
                        + "left join (     "
                        + "select  v_Type as v_Refund     "
                        + "from voucher_Type vt      "
                        + "where vt.short_Name in ('" + pvc.LAB_REFUND_RECEIPT + "')     "
                        + ") vtrf on 1=1 "
                        + "where vt.short_Name in ('" + pvc.LAB_REGISTRATION + "')     "
                        + ") as tbl     "
                        + "group by entryPoint, v_Type";
                DmServer.executeSQL(sqlQuery, cnTemp);

            }

        } catch (Exception ex) {
            refreshDataStructure.addResultLog("iniHL7", "", this.getClass().getName(), sqlQuery, ex.getMessage());
            throw new DmException(0, ex.getMessage());
        } finally {
            if (rsTemp != null) {
                rsTemp.close();
            }
            if (psTemp != null) {
                psTemp.close();
            }
        }
    }

    private void iniDiscountGivenByFilteration(Connection cnTemp) throws Exception {
        DmPreparedStatement psTemp = null;
        ResultSet rsTemp = null;
        String sqlQuery = "", codeValue = "";
        ProjectVoucherCategory pvc = new ProjectVoucherCategory();
        try {

            if (DmShared.vNull(DmServer.executeScalar("Select Count(*) As Cnt From acFilteration;", cnTemp)) <= 0) {

                codeValue = DmServer.getSerialNoInteger("1", "hl7Mast", cnTemp);
                sqlQuery = "insert into acFilteration (v_Type, nature, u_Name, U_EntDt)  "
                        + "select  vt.v_Type, sgn.code as nature, 'SA' as u_Name, GETDATE() as U_EntDt  "
                        + "from voucher_Type vt \n "
                        + "left join subGroupNature sgn on 1 = 1 and sgn.manualCode = 'CN' "
                        + "where category in ('" + pvc.OPD + "','" + pvc.EMERGENCY_OPD + "','" + pvc.OPD_SERVICE + "','" + pvc.OPD_DISCOUNT + "','" + pvc.IPD_BILL + "','" + pvc.LAB_REGISTRATION + "','" + pvc.LAB_DISCOUNT + "','" + pvc.DAY_CARE_DISCOUNT + "','" + pvc.PHARMACY_BILL_FINAL_DISCOUNT + "','" + pvc.DAY_CARE_BILL + "','" + pvc.EMERGENCY_BILL + "')  ";
                DmServer.executeSQL(sqlQuery, cnTemp);

            }

        } catch (Exception ex) {
            refreshDataStructure.addResultLog("iniHL7", "", this.getClass().getName(), sqlQuery, ex.getMessage());
            throw new DmException(0, ex.getMessage());
        } finally {
            if (rsTemp != null) {
                rsTemp.close();
            }
            if (psTemp != null) {
                psTemp.close();
            }
        }
    }

    private void iniFileTypeMast(Connection cnTemp) throws Exception {
        DmPreparedStatement psTemp = null;
        ResultSet rsTemp = null;
        String sqlQuery = "";
        try {
            for (ProjectRuleCode prc : ProjectRuleCode.values()) {
                if (DmShared.vNull(DmServer.executeScalar("Select Count(*) As Cnt From " + DmServer.dbCompany + ".dbo.fileTypeMast ftm Where ftm.ruleCode = '" + prc.getRuleCode() + "'", cnTemp)) <= 0) {
                    sqlQuery = "insert into " + DmServer.dbCompany + ".dbo.fileTypeMast(ruleCode,description,fileType,maxSize,isDefault,extFilters,u_Name,u_EntDt) "
                            + "values ('" + prc.getRuleCode() + "','" + prc.getDescription() + "','" + prc.getFileType() + "'," + prc.getSize() + ",1,'" + prc.getFilters() + "','SA',getdate()) ";
                } else {
                    sqlQuery = "update  " + DmServer.dbCompany + ".dbo.fileTypeMast set  description = '" + prc.getDescription() + "' , u_Name = 'SA' , u_EntDt = getdate()  where ruleCode ='" + prc.getRuleCode() + "'";
                }
                DmServer.executeSQL(sqlQuery, cnTemp);
            }
            for (LibraryRuleCode lrc : LibraryRuleCode.values()) {
                if (DmShared.vNull(DmServer.executeScalar("Select Count(*) As Cnt From " + DmServer.dbCompany + ".dbo.fileTypeMast ftm Where ftm.ruleCode = '" + lrc.getRuleCode() + "'", cnTemp)) <= 0) {
                    sqlQuery = "insert into " + DmServer.dbCompany + ".dbo.fileTypeMast(ruleCode,description,fileType,maxSize,isDefault,extFilters,u_Name,u_EntDt) "
                            + "values ('" + lrc.getRuleCode() + "','" + lrc.getDescription() + "','" + lrc.getFileType() + "'," + lrc.getSize() + ",1,'" + lrc.getFilters() + "','SA',getdate()) ";
                } else {
                    sqlQuery = "update  " + DmServer.dbCompany + ".dbo.fileTypeMast set  description = '" + lrc.getDescription() + "', u_Name = 'SA' , u_EntDt = getdate()  where ruleCode ='" + lrc.getRuleCode() + "'";
                }
                DmServer.executeSQL(sqlQuery, cnTemp);
            }

        } catch (Exception ex) {
            refreshDataStructure.addResultLog("iniFileTypeMast", "", this.getClass().getName(), sqlQuery, ex.getMessage());
            throw new DmException(0, ex.getMessage());
        } finally {
            if (rsTemp != null) {
                rsTemp.close();
            }
            if (psTemp != null) {
                psTemp.close();
            }
        }
    }

